import os
from datetime import datetime, timedelta
from google.cloud import monitoring_v3
from google.api_core.exceptions import GoogleAPIError

def compare_metrics_between_resources(project_id, metric_type, resource1_filter, resource2_filter, start_time=None, end_time=None):
    """
    Compare metric values between two resources using Google Cloud Monitoring API

    Args:
        project_id (str): Google Cloud project ID
        metric_type (str): The metric type to query (e.g., 'compute.googleapis.com/instance/cpu/utilization')
        resource1_filter (str): Filter for first resource (e.g., 'resource.label.instance_id="instance-1"')
        resource2_filter (str): Filter for second resource (e.g., 'resource.label.instance_id="instance-2"')
        start_time (datetime): Start time for the query window
        end_time (datetime): End time for the query window

    Returns:
        dict: Comparison results with metric values for both resources
    """

    # Set default time window if not provided
    if end_time is None:
        end_time = datetime.utcnow()
    if start_time is None:
        start_time = end_time - timedelta(hours=1)

    # Create the client
    client = monitoring_v3.MetricServiceClient()

    # Format time range
    start_time_proto = start_time.replace(tzinfo=None)
    end_time_proto = end_time.replace(tzinfo=None)

    # Query metrics for first resource
    try:
        resource1_results = client.list_time_series(
            request={
                "name": f"projects/{project_id}",
                "filter": f"metric.type=\"{metric_type}\" AND {resource1_filter}",
                "interval": {
                    "start_time": start_time_proto,
                    "end_time": end_time_proto
                },
                "view": monitoring_v3.ListTimeSeriesRequest.TimeSeriesView.FULL,
                "aggregation": {
                    "alignment_period": {"seconds": 60},
                    "per_series_aligner": monitoring_v3.Aggregation.Aligner.ALIGN_MEAN
                }
            }
        )
    except GoogleAPIError as e:
        raise Exception(f"Error querying metrics for resource 1: {e}")

    # Query metrics for second resource
    try:
        resource2_results = client.list_time_series(
            request={
                "name": f"projects/{project_id}",
                "filter": f"metric.type=\"{metric_type}\" AND {resource2_filter}",
                "interval": {
                    "start_time": start_time_proto,
                    "end_time": end_time_proto
                },
                "view": monitoring_v3.ListTimeSeriesRequest.TimeSeriesView.FULL,
                "aggregation": {
                    "alignment_period": {"seconds": 60},
                    "per_series_aligner": monitoring_v3.Aggregation.Aligner.ALIGN_MEAN
                }
            }
        )
    except GoogleAPIError as e:
        raise Exception(f"Error querying metrics for resource 2: {e}")

    # Extract and process results
    resource1_values = []
    resource2_values = []

    for time_series in resource1_results:
        for point in time_series.points:
            if point.value.double_value is not None:
                resource1_values.append(point.value.double_value)

    for time_series in resource2_results:
        for point in time_series.points:
            if point.value.double_value is not None:
                resource2_values.append(point.value.double_value)

    # Calculate averages if we have data
    avg_resource1 = sum(resource1_values) / len(resource1_values) if resource1_values else 0
    avg_resource2 = sum(resource2_values) / len(resource2_values) if resource2_values else 0

    return {
        "metric_type": metric_type,
        "resource1": {
            "filter": resource1_filter,
            "average_value": avg_resource1,
            "sample_count": len(resource1_values)
        },
        "resource2": {
            "filter": resource2_filter,
            "average_value": avg_resource2,
            "sample_count": len(resource2_values)
        },
        "difference": avg_resource1 - avg_resource2,
        "time_window": {
            "start": start_time.isoformat(),
            "end": end_time.isoformat()
        }
    }

